using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

/// <summary>
/// MCP tools that wrap the JSONPlaceholder REST API.
/// Non-static class — services are injected via the constructor.
/// </summary>
[McpServerToolType]
public class ApiTools(IHttpClientFactory httpClientFactory, ILogger<ApiTools> logger)
{
    private HttpClient CreateClient() => httpClientFactory.CreateClient("api");

    [McpServerTool, Description("Get a post by its numeric ID from the API.")]
    public async Task<string> GetPost(
        [Description("The post ID (1-100)")] int id,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching post {Id}", id);
        var client = CreateClient();
        var json = await client.GetStringAsync($"/posts/{id}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("List posts, optionally filtered by user ID.")]
    public async Task<string> ListPosts(
        [Description("Filter by user ID (optional)")] int? userId = null,
        CancellationToken cancellationToken = default)
    {
        var client = CreateClient();
        var url = userId.HasValue ? $"/posts?userId={userId}" : "/posts";
        var json = await client.GetStringAsync(url, cancellationToken);

        // Return a summary instead of the full payload
        using var doc = JsonDocument.Parse(json);
        var count = doc.RootElement.GetArrayLength();
        return $"Found {count} posts.\n{json}";
    }

    [McpServerTool, Description("Get all comments for a specific post.")]
    public async Task<string> GetComments(
        [Description("The post ID to get comments for")] int postId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching comments for post {PostId}", postId);
        var client = CreateClient();
        return await client.GetStringAsync($"/posts/{postId}/comments", cancellationToken);
    }

    [McpServerTool, Description("Create a new post (simulated by the API).")]
    public async Task<string> CreatePost(
        [Description("Title of the new post")] string title,
        [Description("Body content of the post")] string body,
        [Description("Author user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating post for user {UserId}", userId);
        var client = CreateClient();
        var payload = new { title, body, userId };
        var response = await client.PostAsJsonAsync("/posts", payload, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

